        $now = now();

        DB::table('module_library_items')->updateOrInsert(
            ['module_code' => 'MULTIVARIATE-ANALYSIS-BASIC-V2'],
            [
                'module_no' => 16,
                'title' => 'Multivariate Analysis',
                'year_level' => 'Year 3',
                'version_no' => 2,
                'version_name' => 'Multivariate Analysis Practice and MCQ Review',
                'version_code' => 'V2',
                'description' => 'PCA, factor analysis, cluster analysis, discriminant analysis, and canonical correlation for high-dimensional data. This version emphasizes code tracing, worked practice, debugging, MCQ reasoning, comparison of methods, and mastery evidence.',
                'estimated_minutes' => 740,
                'sort_order' => 47,
                'is_active' => true,
                'created_at' => $now,
                'updated_at' => $now,
            ]
        );

        DB::table('module_library_items')
            ->where('module_code', 'MULTIVARIATE-ANALYSIS-BASIC-V2')
            ->update([
                'content_sections' => json_encode($this->contentSections(), JSON_UNESCAPED_UNICODE),
                'updated_at' => now(),
            ]);

        DB::table('module_library_items')
            ->where('module_code', 'MULTIVARIATE-ANALYSIS-BASIC-V2')
            ->update([
                'mcq_questions' => json_encode($this->mcqQuestions(), JSON_UNESCAPED_UNICODE),
                'updated_at' => now(),
            ]);
    }

